def _one_forest(X,trees):
    out=np.zeros(X.shape[0])
    for left,right,feat,thr,val in trees:
        for r in range(X.shape[0]):
            node=0
            while left[node]!=-1:
                node=left[node] if X[r,feat[node]]<=thr[node] else right[node]
            out[r]+=val[node]
    return out/max(len(trees),1)
def _rf_predict(X,nt):
    idx=[k for k,c in enumerate(_RF_CUTOFFS) if c<=nt]
    if not idx:return np.zeros(X.shape[0])
    idx=idx[-3:]
    ww=np.array([1.0**(len(idx)-1-j) for j in range(len(idx))],dtype=float);ww/=ww.sum()
    return sum(w*_one_forest(X,_RF_FORESTS[k]) for w,k in zip(ww,idx))

