def _ar_feature(logp):
    r=np.diff(logp,axis=1)
    if r.shape[1]<40:return None
    ss=np.stack([r[:,-h:].sum(1) for h in _AR_H],axis=1)
    zz=(ss-ss.mean(0,keepdims=True))/(ss.std(0,keepdims=True)+1e-9)
    return np.c_[ss,zz].reshape(-1)

def _ar_predict(logp,nt):
    f=_ar_feature(logp)
    if f is None:return 0.0
    eligible=[x for x in _AR_MODELS if x[0]<=nt]
    if not eligible:return 0.0
    _,xm,xs,co,ic=eligible[-1]
    return float(((f-xm)/np.maximum(xs,1e-12))@co+ic)

