def _meta_pls_predict(X,nt,models):
    eligible=[m for m in models if m[0]<=nt]
    if not eligible:return np.zeros(X.shape[0])
    eligible=eligible[-3:]
    return np.mean([X@b+ic for _,b,ic in eligible],axis=0)


def _fit_var(z,mode="abs",W=150,L=5,lam=200.0):
    zz=z[:,-min(W,z.shape[1]):]
    if zz.shape[1]<=L+20:return None
    raw=np.stack([zz[:,q-L:q][:,::-1].reshape(-1) for q in range(L,zz.shape[1])])
    if mode=="abs": X=np.c_[raw,np.abs(raw)]
    elif mode=="tail": X=np.c_[raw,np.maximum(raw-0.5,0.0),np.minimum(raw+0.5,0.0)]
    else: X=raw
    Y=zz[:,L:].T
    xm=X.mean(0);ym=Y.mean(0);XC=X-xm;YC=Y-ym
    # Dual ridge: substantially cheaper than solving in the expanded feature space.
    dual=np.linalg.solve(XC@XC.T+lam*np.eye(len(XC)),YC)
    B=XC.T@dual
    return (xm,ym,B,L,mode)

def _predict_var(z,model):
    if model is None:return None
    xm,ym,B,L,mode=model
    raw=z[:,-L:][:,::-1].reshape(-1)
    if mode=="abs": x=np.r_[raw,np.abs(raw)]
    elif mode=="tail": x=np.r_[raw,np.maximum(raw-0.5,0.0),np.minimum(raw+0.5,0.0)]
    else: x=raw
    return (x-xm)@B+ym

def getMyPosition(prcSoFar):
    # prcSoFar is a numpy array, shape (nInstruments, nDays)
    # must return an array of integer positions, one per instrument
    global state
    n,nt=prcSoFar.shape
    if nt<state.get("last_nt",-1): state=_new_state()
    state["last_nt"]=nt
    if nt<WARMUP: return np.zeros(n,dtype=int)
    logp=np.log(prcSoFar)
    _update_factor(logp,nt)
    Z,bl=residualize(logp)
    zres,rc=resid_z(logp)

    if nt-state["scanned"]>=RESCAN:
        units,used=[],set()
        for i,j in SEED_PAIRS:
            if j<n:
                sp=(logp[i]-logp[j])[None,:]
                _,t=ar1_t(sp)
                if t[0]<T_KEEP and rec_t(sp[0])<KEEPR:
                    units.append(("P",i,j)); used.update((i,j))
        _,ts=ar1_t(Z[1:])
        cand=[(ts[i-1],i) for i in SEED_SINGLES
              if i<n and i not in used and ts[i-1]<T_KEEP and rec_t(Z[i])<KEEPR]
        cand+=[(ts[k],k+1) for k in np.where(ts<T_SINGLE)[0] if (k+1) not in used]
        cand.sort(); ns=0
        for t,i in cand:
            if i in used or ns>=MAX_SNG: continue
            units.append(("S",i)); used.add(i); ns+=1
        state["gunits"]=[(i,j) for t,i,j in scan_gray(logp,n,used)]
        state["bunits"]=[]
        if BIRTHW>0 and nt>BIRTHW+60:
            Lw=logp[:,-BIRTHW:]; Lc2=Lw-Lw.mean(1,keepdims=True)
            Lf=logp-logp.mean(1,keepdims=True)
            for i in range(1,n-1):
                if i in used: continue
                x=Lc2[i]; xx=max(x@x,1e-30)
                for j in range(i+1,n):
                    if j in used: continue
                    b=(Lc2[j]@x)/xx; R=Lc2[j]-b*x
                    _,tt=ar1_t(R[None,:])
                    if tt[0]<BGATE and abs(b)<4:
                        xf=Lf[i]; bf=(Lf[j]@xf)/max(xf@xf,1e-30)
                        _,tf=ar1_t((Lf[j]-bf*xf)[None,:])
                        if tf[0]>-2.6:
                            state["bunits"].append((j,i))
        zz=zres[:,-min(200,zres.shape[1]):]
        mats=[]
        for lag in (1,2,3):
            aa=zz[:,:-lag];bb=zz[:,lag:]
            M=(aa@bb.T)/max(aa.shape[1],1);np.fill_diagonal(M,0.0);M[0,:]=0.0;M[:,0]=0.0;mats.append(M)
        state["L"]=mats
        state["var_models"]={
            "abs":_fit_var(zres[1:],mode="abs",W=150,L=5,lam=200.0),
            "lin":_fit_var(zres[1:],mode="lin",W=150,L=5,lam=1000.0),
            "tail":_fit_var(zres[1:],mode="tail",W=150,L=5,lam=1000.0),
            "robust2":_fit_var(zres[1:],mode="lin",W=150,L=2,lam=1000.0),
        }
        core=set(used)
        for i,j in state["gunits"]: core.update((i,j))
        state["core"]=core
        state["scanned"]=nt; state["units"]=units
        r=np.diff(logp,axis=1); r=r-r.mean(axis=1,keepdims=True)
        state["rbeta"]=(r@r[0])/max(r[0]@r[0],1e-30)

    px=prcSoFar[:,-1]
    if state.get("rel_prev_px") is not None:
        _rel_move=px-state["rel_prev_px"]
        _rel_pnl=state["rel_prev"]*_rel_move-state["rel_cost"]
        state.setdefault("rel_hist",[]).append(_rel_pnl)
    if state.get("vx_prev_px") is not None:
        move=px[1:]-state["vx_prev_px"][1:]
        bp=float(state["vx_base_prev"]@move-state["vx_base_cost"])
        state.setdefault("vx_base_pnl",[]).append(bp)
        for ek,ep in state["vx_prev"].items():
            val=float(ep@move-state["vx_cost"][ek])
            state.setdefault("vx_inc",{}).setdefault(ek,[]).append(val-bp)
    if state.get("pi_prev_px") is not None:
        _mv=px[1:]-state["pi_prev_px"][1:]
        _bp=state["pi_base_prev"]*_mv-state["pi_base_cost"]
        for _ek,_ep in state["pi_prev"].items():
            _vv=_ep*_mv-state["pi_cost"][_ek]-_bp
            state.setdefault("pi_inc",{}).setdefault(_ek,[]).append(_vv)
        _pb=float(state["pls_base_prev"]@_mv-state["pls_base_cost"])
        for _pk,_pp in state["pls_prev"].items():
            _pv=float(_pp@_mv-state["pls_cost"][_pk])
            state.setdefault("pls_inc",{}).setdefault(_pk,[]).append(_pv-_pb)
    if state.get("ar_pending_sign") is not None:
        rr0=px[0]/state["ar_pending_px"]-1.0
        state.setdefault("ar_pnl",[]).append(float(100_000.0*state["ar_pending_sign"]*rr0-state["ar_pending_cost"]))
    ar_pred=_ar_predict(logp,nt); ar_sign=float(np.sign(ar_pred))
    ar_prev=float(state.get("ar_last_sign",0.0)); ar_cost=2.0*abs(ar_sign-ar_prev)
    state["ar_pending_sign"]=ar_sign;state["ar_pending_px"]=float(px[0]);state["ar_pending_cost"]=ar_cost;state["ar_last_sign"]=ar_sign
    ar_hist=state.get("ar_pnl",[])[-40:];ar_active=False
    if len(ar_hist)>=20:
        ah=np.asarray(ar_hist);ar_sr=float(np.sqrt(250.0)*ah.mean()/(ah.std()+1e-12));ar_active=bool(ar_sr>0.5)
    Wsl=slice(-WIN,None)
